function run($changes,$expected,$paid=true){$GLOBALS['o']=new WC_Order;$GLOBALS['o']->paid=$paid;$_POST=array_replace(['order_id'=>10,'token'=>'ok','order_key'=>'real-key','rating'=>'1','comment'=>'<script>bad</script>Nice'],$changes);try{sa_order_experience_save();}catch(Exception $e){assert($e->getMessage()===$expected);if($expected!=='saved')assert(!$GLOBALS['o']->meta);} }
